    bg = grid[0][0]
    seen = set()
    from collections import deque
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = []
            outside = False
            while q:
                x, y = q.popleft()
                region.append((x, y))
                if x == 0 or y == 0 or x == h-1 or y == w-1:
