 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # In all demos, every cell of the majority/background color that occurs
    # in an exceptional-color row or column is recolored 2.
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h):
        if any(v != bg for v in grid[r]):
            for c in range(w):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        if any(grid[r][c] != bg for r in range(h)):
            for r in range(h):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
